import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';

@Component({
  selector: 'app-customized-dot',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <span class="customized-dot-wrapper" [title]="tooltip()">
      <span class="customized-dot"></span>
      @if (showReset()) {
        <button class="reset-link" (click)="resetClicked.emit(); $event.stopPropagation()">
          Reset
        </button>
      }
    </span>
  `,
  styles: [`
    .customized-dot-wrapper {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      cursor: help;
    }
    .customized-dot {
      display: inline-block;
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #f59e0b;
      flex-shrink: 0;
    }
    .reset-link {
      background: none;
      border: none;
      color: #6b7280;
      font-size: 11px;
      cursor: pointer;
      padding: 0;
      text-decoration: underline;
    }
    .reset-link:hover {
      color: #374151;
    }
  `]
})
export class CustomizedDot {
  /** Tooltip text explaining the customization */
  tooltip = input('This item has been customized from the default');

  /** Whether to show the inline "Reset" link */
  showReset = input(false);

  /** Emitted when "Reset" is clicked */
  resetClicked = output<void>();
}
